'use strict';
const $=s=>document.querySelector(s), app=$('#app'), modal=$('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const day=(offset=0)=>{const d=new Date();d.setDate(d.getDate()+offset);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const pretty=d=>new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});
const money=n=>'₹'+Number(n).toLocaleString('en-IN');
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,5);
const KEY='my-doctor-mvp-v1';
function doctorDefaults(index){return {photo:`assets/doctors/d${index}.jpg`,clinic:['Bluebell Family Clinic','Heartwell Cardiac Clinic','Clear Skin Care','Little Steps Children’s Clinic','Bloom Women’s Care','Move Well Orthopedic Clinic','Clear Voice ENT Clinic','Everyday Care Clinic'][index],city:'Pune',languages:'English, Hindi',bio:'Thoughtful care, clear guidance, and time for your questions. This is a fictional demonstration profile.'};}
function seed(){return {profile:{id:'self',name:'Aarav Mehta',age:29,gender:'Male',mobile:'9000000001',emergency:'9000000002',blocked:false,consent:true},family:[{id:'f1',name:'Meera Mehta',age:54,gender:'Female',relationship:'Mother'},{id:'f2',name:'Rohan Mehta',age:24,gender:'Male',relationship:'Brother'}],doctors:[['Ananya Sharma','General Physician','MBBS, MD',12,500,'👩🏻‍⚕️'],['Vikram Rao','Cardiologist','MBBS, DM Cardiology',18,900,'👨🏽‍⚕️'],['Neha Kapoor','Dermatologist','MBBS, MD Dermatology',9,650,'👩🏽‍⚕️'],['Arjun Patel','Pediatrician','MBBS, DCH',11,600,'👨🏻‍⚕️'],['Kavita Iyer','Gynecologist','MBBS, MS',14,750,'👩🏻‍⚕️'],['Rohit Verma','Orthopedic','MBBS, MS Orthopedics',15,800,'👨🏽‍⚕️'],['Sana Khan','ENT','MBBS, MS ENT',8,550,'👩🏽‍⚕️'],['Dev Malhotra','General Physician','MBBS, MD',6,450,'👨🏻‍⚕️']].map((d,i)=>({...doctorDefaults(i),id:'d'+i,name:'Dr. '+d[0],speciality:d[1],qualification:d[2],experience:d[3],fee:d[4],avatar:d[5],status:'Approved',blocked:false,mobile:'90000000'+String(i+10),registration:'DEMO-MCI-'+(1000+i),days:['Mon','Tue','Wed','Thu','Fri','Sat'],start:'09:00',end:'17:00',duration:30})),appointments:[{id:'APT-DEMO-101',doctor:'d0',patient:'self',date:day(),time:'10:30',type:'Offline',token:12,status:'Scheduled',payment:'Successful',fee:500},{id:'APT-DEMO-102',doctor:'d1',patient:'f1',date:day(1),time:'11:00',type:'Online',token:9,status:'Scheduled',payment:'Successful',fee:900},{id:'APT-DEMO-100',doctor:'d0',patient:'self',date:day(-5),time:'09:00',type:'Offline',token:5,status:'Completed',payment:'Successful',fee:500}],queues:{},records:[{id:'r1',title:'Annual health check-up',type:'Lab Report',patient:'self',date:day(-10),source:'Demo Diagnostics',filename:'health-summary-demo.pdf',notes:'Fictional report for prototype demonstration.'}],prescriptions:[{id:'rx1',doctor:'d0',patient:'self',date:day(-5),notes:'Rest and maintain hydration. Fictional demonstration only.',medicines:[{name:'Demo medicine A',dosage:'1 tablet',frequency:'After breakfast',duration:'3 days',instructions:'Prototype sample, not medical advice.'}]}],notifications:[{id:'n1',title:'Your appointment is confirmed',message:'Your appointment with Dr. Ananya Sharma is ready. Token #12.',audience:'patient',read:false,link:'appointments'},{id:'n2',title:'Welcome to My Doctor',message:'Your demo health companion is ready.',audience:'all',read:false,link:'home'},{id:'n3',title:'Upcoming appointment reminder',message:'Meera has an appointment tomorrow with Dr. Vikram Rao.',audience:'patient',read:false,link:'appointments'}],complaints:[{id:'SUP-101',user:'Aarav Mehta',subject:'Payment receipt request',message:'Please help me find the invoice for my recent appointment.',date:day(),status:'Open'}],commission:10,logs:[{date:new Date().toISOString(),actor:'System',action:'Demo data initialized',module:'Platform',reference:'DEMO',status:'Success'}],roles:{'Super Admin':['View','Add','Edit'],'Operations':['View','Edit'],'Support':['View']},directory:{Hospital:[{name:'Demo City Hospital',city:'Pune',status:'Active'}],Pharmacy:[{name:'Demo Care Pharmacy',city:'Mumbai',status:'Active'}]}};}
let state;try{state=JSON.parse(localStorage.getItem(KEY))||seed();}catch{state=seed();}
state.doctors.forEach(d=>{const defaults=/^d[0-7]$/.test(d.id)?doctorDefaults(Number(d.id.slice(1))):{clinic:'',city:'',languages:'English, Hindi',bio:''};Object.entries(defaults).forEach(([key,value])=>{if(d[key]===undefined)d[key]=value;});});
let role='',screen='launcher',adminTab='Dashboard',doctorId='d0',filter='All',appointmentTab='Today',selectedPatient='self',search='',doctorDay=day(),booking=null,authRole='',authMobile='',newDoctor=false;
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Storage is full. Please remove a large uploaded file.');}}
function audit(action,module,reference='—'){state.logs.unshift({date:new Date().toISOString(),actor:role||'Demo',action,module,reference,status:'Success'});save();}
function notify(title,message,audience='patient',link='appointments'){state.notifications.unshift({id:uid('N'),title,message,audience,link,read:false});save();}
function toast(message){const globalToast=$('#toast'),dialogToast=$('#dialog-feedback');globalToast.style.display='none';if(dialogToast)dialogToast.style.display='none';const target=modal.open&&dialogToast?dialogToast:globalToast;target.textContent=message;target.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>target.style.display='none',3600);}
function doctor(id){return state.doctors.find(d=>d.id===id)||state.doctors[0];}
function patient(id){return id==='self'?state.profile:state.family.find(p=>p.id===id)||{name:'Archived family member',age:'—',gender:'—'};}
const iconPaths={heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',home:'m3 10 9-7 9 7M5 9v12h5v-7h4v7h5V9',doctor:'M6 3v5a5 5 0 0 0 10 0V3M4 3h4m6 0h4M11 13v2a6 6 0 0 0 12 0v-2M21 9a2 2 0 1 0 0 4 2 2 0 0 0 0-4',calendar:'M8 2v4m8-4v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm3 10h1m6 0h1m-8 4h1m6 0h1',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',record:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8l-6-6Zm0 0v6h6M8 13h8m-8 4h5',prescription:'M5 20V4h6a4 4 0 0 1 0 8H5m5 0 10 10m0-10L10 22',family:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.9M13 3.1a4 4 0 0 1 0 7.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',profile:'M20 21v-2a7 7 0 0 0-14 0v2M17 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9m-11 9h10m-8 4h2',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',shield:'m12 2 9 4v6c0 5-4 8-9 10-5-2-9-5-9-10V6l9-4Zm-4 10 3 3 5-6',switch:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',grid:'M3 3h7v7H3V3Zm11 0h7v7h-7V3ZM3 14h7v7H3v-7Zm11 0h7v7h-7v-7Z',close:'m6 6 12 12M18 6 6 18',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0Z'};
Object.assign(iconPaths,{download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',upload:'M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5',back:'M19 12H5m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',edit:'m16 3 5 5-12 12-6 1 1-6L16 3Zm-2 2 5 5',location:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Zm-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',phone:'M5 3h4l2 5-3 2c2 4 3 5 7 7l2-3 5 2v4c0 2-4 3-8 1C8 18 5 15 3 9 1 5 3 3 5 3Z',lock:'M6 10V7a6 6 0 0 1 12 0v3M4 10h16v12H4V10Zm8 5v3',menu:'M4 6h16M4 12h16M4 18h16',notes:'M5 3h14v18H5V3Zm4 5h6m-6 4h6m-6 4h4',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z'});
function icon(name,extra=''){return `<svg class="ui-icon ${extra}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.heart}"/></svg>`;}
function doctorPhoto(d){const source=d.photo||(/^d[0-7]$/.test(d.id)?`assets/doctors/${d.id}.jpg`:'');return /^(?:assets\/[\w/.-]+|https:\/\/[^\s"<>]+|data:image\/(?:jpeg|png|webp);base64,[a-zA-Z0-9+/=]+)$/.test(source)?source:'';}
function doctorAvatar(d){const photo=doctorPhoto(d),initials=d.name.replace(/^Dr\.?\s*/i,'').split(/\s+/).slice(0,2).map(p=>p[0]).join('');return `<span class="avatar doctor-avatar doctor-photo-${esc(d.id)}" aria-hidden="true">${photo?`<img src="${esc(photo)}" alt="" width="120" height="144" loading="lazy" decoding="async">`:`<span>${esc(initials)}</span>`}</span>`;}
function btn(label,action,extra='',kind=''){const content=label.replace(/\s*→/g,' '+icon('arrow')).replace(/\s*↓/g,' '+icon('download')).replace(/←\s*/g,icon('back')+' ').replace(/\s*✓/g,' '+icon('check')).replace(/\s+\+$/,' '+icon('plus'));return `<button class="btn ${kind}" data-action="${action}" ${extra}>${content}</button>`;}
function empty(message){return `<div class="card empty">${message}</div>`;}
function heading(title,subtitle='',action=''){return `<div class="row page-heading"><div><div class="eyebrow">${role==='admin'?'Platform management':role==='doctor'?'Doctor workspace':'Your health, made simple'}</div><h2>${title}</h2>${subtitle?`<p class="muted">${subtitle}</p>`:''}</div>${action}</div>`;}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,name,values,current=''){return `<label>${label}<select name="${name}">${values.map(v=>{let a=Array.isArray(v)?v:[v,v];return `<option value="${esc(a[0])}" ${a[0]===current?'selected':''}>${esc(a[1])}</option>`;}).join('')}</select></label>`;}
function patientSelect(name='patient',current=selectedPatient){return select('Patient',name,[['self',state.profile.name+' (Self)'],...state.family.map(p=>[p.id,p.name])],current);}
function dialog(title,content){modal.innerHTML=`<div class="dialog-heading"><h2>${title}</h2><button class="plain icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button><div id="dialog-feedback" class="dialog-feedback" role="status" aria-live="polite"></div></div><div class="dialog-content">${content}</div>`;if(!modal.open)modal.showModal();modal.scrollTop=0;}
function go(next){screen=next;search='';filter='All';render();window.scrollTo(0,0);}
function header(){const authenticated=role&&!['auth','otp','registration','setup'].includes(screen),unread=state.notifications.filter(n=>(n.audience===role||n.audience==='all')&&!n.read).length;return `<header class="app-header"><button class="plain brand" data-action="home" aria-label="My Doctor home"><span class="logo">${icon('heart')}<b>+</b></span><span class="brand-copy"><span>My <em>Doctor</em></span><small>YOUR HEALTH. OUR PRIORITY.</small></span></button><div class="header-actions">${authenticated?`<span class="badge header-caption">${role==='patient'?'Patient app':role==='doctor'?'Doctor workspace':'Admin panel'}</span><button class="plain icon-button notification-button" data-action="notifications" aria-label="Notifications${unread?', '+unread+' unread':''}">${icon('bell')}${unread?`<span class="notification-dot">${unread}</span>`:''}</button>`:''}<button class="plain icon-button switch-button" data-action="launcher" aria-label="Switch workspace" title="Switch workspace">${icon('switch')}<span class="switch-label">Switch role</span></button>${authenticated?`<button class="profile-button" data-action="profile" aria-label="Your profile">${role==='patient'?esc(state.profile.name.charAt(0)):role==='doctor'?'Dr':icon('grid')}</button>`:''}</div></header>`;}
function navigation(){if(!role||screen==='auth'||screen==='otp'||screen==='registration'||screen==='setup'||role==='admin')return '';const items=role==='patient'?[['home','home','Home'],['doctors','doctor','Doctors'],['appointments','calendar','Appointments'],['records','record','Records'],['profile','profile','Profile']]:[['home','home','Dashboard'],['schedule','calendar','Schedule'],['queue','clock','Queue'],['notifications','bell','Updates'],['profile','profile','Profile']];return `<nav class="bottom-nav" aria-label="Main navigation">${items.map(([s,i,l])=>`<button class="${screen===s?'active':''}" ${screen===s?'aria-current="page"':''} data-action="navigate" data-screen="${s}"><span class="nav-icon">${icon(i)}</span><span>${l}</span></button>`).join('')}</nav>`;}
function render(){let content;if(screen==='launcher')content=launcher();else if(screen==='auth'||screen==='otp')content=auth();else if(screen==='setup')content=profileForm(true);else if(screen==='registration')content=registration();else if(role==='admin')content=admin();else if(screen==='notifications')content=notifications();else if(screen==='profile')content=profile();else if(screen==='family')content=family();else if(screen==='records')content=records();else if(screen==='prescriptions')content=prescriptions();else if(screen==='queue')content=queue();else if(role==='doctor')content=doctorPanel();else if(screen==='doctors')content=doctors();else if(screen==='appointments')content=appointments();else content=home();document.body.dataset.role=role;document.body.dataset.screen=screen;app.innerHTML=header()+`<main class="wrap screen-${screen}">${content}</main>`+navigation();}
function launcher(){return `<div class="welcome"><span class="welcome-mark">${icon('heart')}</span><div class="eyebrow">A little care. A healthier tomorrow.</div><h1>Good health starts with<br><span>the right connection.</span></h1><p class="muted">Your doctor. Your family. Your care.<br>All in one thoughtful place.</p><span class="demo-label"><i></i> INTERACTIVE DEMO</span></div><div class="grid roles">${[['patient','heart','Patient app','Find a doctor, book a visit, and care for your family.'],['doctor','doctor','Doctor workspace','Appointments, patient history, and prescriptions.'],['admin','grid','Admin panel','Your healthcare network, beautifully organized.']].map(([r,i,t,p])=>`<button class="card role role-${r}" data-action="role" data-role="${r}"><span class="icon">${icon(i)}</span><span class="role-copy"><strong>${t}</strong><span>${p}</span></span><span class="role-arrow">${icon('chevron')}</span></button>`).join('')}</div><div class="demo-footer"><span>${icon('shield')} Fictional data. Connected workspaces.</span><button class="plain" data-action="reset">Reset demo ${icon('switch')}</button></div><p class="footer-note">Made for a healthier tomorrow.</p>`;}
function auth(){return `<div class="narrow card"><span class="icon">${icon(authRole==='doctor'?'doctor':'heart')}</span><div class="eyebrow">Welcome to My Doctor</div><h1>${screen==='otp'?'Verify your number':'Care is just a step away.'}</h1><p class="muted">${screen==='otp'?'Enter the demo OTP sent to +91 '+esc(authMobile):'Sign in to your '+authRole+' workspace.'}</p><form id="auth-form">${screen==='otp'?field('Verification code','otp','','text','required pattern="1234" inputmode="numeric" maxlength="4" autocomplete="one-time-code" placeholder="1234"'):`${field('Mobile number','mobile',authRole==='patient'?'9000000001':'9000000010','tel','required pattern="[6-9][0-9]{9}" maxlength="10" placeholder="10-digit mobile number"')}${authRole==='doctor'?'<label><input type="checkbox" name="newDoctor"> Register as a new doctor</label>':'<label><input type="checkbox" name="newPatient"> Create a new patient profile</label>'}`}<p class="notice section">${screen==='otp'?'Demo OTP: <strong>1234</strong>':'Use any valid 10-digit Indian mobile number. No SMS is sent.'}</p>${btn(screen==='otp'?'Verify & continue →':'Send demo OTP →','submit','type="submit"')}</form>${screen==='otp'?'<button class="plain section" data-action="resend">Resend OTP</button>':''}</div>`;}
function home(){const upcoming=state.appointments.filter(a=>a.status==='Scheduled'&&a.date>=day()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),active=upcoming[0],recent=state.prescriptions.filter(p=>p.patient==='self').at(-1);return `<div class="home-greeting"><div><p>LET’S TAKE CARE OF YOU</p><h2>Hello, ${esc(state.profile.name.split(' ')[0])} <span class="greeting-sun">${icon('sun')}</span></h2></div><span class="greeting-date">${new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short'})}</span></div>${careBanner()}<section class="service-section"><div class="section-heading"><h2>Care at your fingertips</h2><span>Made for you</span></div><div class="grid quick-grid">${[['doctors','doctor','Find Doctor','Your right specialist'],['appointments','calendar','Appointments','All your visits'],['queue','clock','Token / Queue','Skip the uncertainty'],['records','record','Medical Records','Your health story'],['prescriptions','prescription','Prescriptions','Your care plan'],['family','family','Family Members','Care for your loved ones']].map(([s,i,t,p])=>`<button class="card quick quick-${s}" data-action="navigate" data-screen="${s}"><span class="icon">${icon(i)}</span><h3>${t}</h3><small>${p}</small></button>`).join('')}</div></section><div class="grid dashboard-bottom section"><section><div class="section-heading"><h2>Your next appointment</h2><button class="plain text-link" data-action="navigate" data-screen="appointments">View all ${icon('arrow')}</button></div>${active?appointmentCard(active):empty('Your next appointment will appear here.')}${active?`<button class="live-queue" data-action="appointment-queue" data-id="${active.id}"><span class="queue-pulse"></span><span><strong>Your token #${active.token}</strong><small>${queueStatus(active).ahead} ahead · ${queueStatus(active).label}</small></span><span class="queue-link">Track queue ${icon('chevron')}</span></button>`:''}</section><section class="peace-section"><div class="section-heading"><h2>A little peace of mind</h2></div><div class="card safe"><span class="icon">${icon('shield')}</span><div><h3>Your health. Your control.</h3><p>Keep your records and your family’s care together.</p><button class="plain text-link" data-action="navigate" data-screen="profile">Manage privacy ${icon('arrow')}</button></div></div></section></div>${recent?`<section class="section recent-prescription"><div class="section-heading"><h2>Latest prescription</h2></div><button class="card prescription-shortcut" data-action="rx" data-id="${recent.id}"><span class="icon">${icon('prescription')}</span><span><strong>${esc(doctor(recent.doctor).name)}</strong><small>${pretty(recent.date)} · Your care instructions</small></span>${icon('chevron')}</button></section>`:''}<p class="footer-note">A little care goes a long way. ${icon('heart')}</p>`;}
function doctors(){return `${heading('Find your doctor','The right specialist. A little more peace of mind.')}<div class="toolbar doctor-search"><span>${icon('search')}</span><input id="doctor-search" aria-label="Search doctors" placeholder="Search doctor or speciality" value="${esc(search)}"></div><div class="chips speciality-rail" aria-label="Filter by speciality">${['All',...new Set(state.doctors.map(d=>d.speciality))].map(s=>`<button class="chip ${filter===s?'active':''}" data-action="speciality" aria-pressed="${filter===s}" data-value="${esc(s)}">${s==='All'?'All specialists':esc(s)}</button>`).join('')}</div><p class="results-note">Experienced doctors, thoughtful care</p><p class="photo-disclaimer">Demo profiles · Stock photo portraits</p><div class="grid doctor-grid" id="doctor-list">${doctorList()}</div>`;}
function doctorList(){const list=state.doctors.filter(d=>d.status==='Approved'&&!d.blocked&&(filter==='All'||d.speciality===filter)&&(d.name+' '+d.speciality).toLowerCase().includes(search.toLowerCase()));return list.map(d=>`<article class="card doctor"><div class="flex doctor-top">${doctorAvatar(d)}<div><span class="doctor-speciality">${esc(d.speciality)}</span><h3>${esc(d.name)}</h3><p>${esc(d.qualification)}</p><small>${d.experience} years experience</small></div><span class="doctor-check" title="Demo verified profile">${icon('check')}</span></div><div class="doctor-availability"><span class="queue-pulse"></span><span>Available from <strong>${esc(d.start)}</strong></span><span class="demo-profile">Demo profile</span></div><footer class="row"><div class="doctor-fee"><strong>${money(d.fee)}</strong><small> / consultation</small></div>${btn('View profile '+icon('arrow'),'doctor-profile','data-id="'+d.id+'"','secondary')}</footer></article>`).join('')||empty('No doctors match your search. Try another speciality.');}
function slots(d,date){const weekday=new Date(date+'T12:00:00').toLocaleDateString('en-US',{weekday:'short'});if(!d.days.includes(weekday))return [];let [h,m]=d.start.split(':').map(Number),[eh,em]=d.end.split(':').map(Number),result=[];for(let t=h*60+m;t<eh*60+em;t+=Number(d.duration)){let time=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');if(!state.appointments.some(a=>a.doctor===d.id&&a.date===date&&a.time===time&&a.status!=='Cancelled'))result.push(time);}return result;}
function showDoctor(id){
  const d=doctor(id),languages=Array.isArray(d.languages)?d.languages.join(', '):d.languages||'English, Hindi';
  dialog('Meet your doctor',`<div class="doctor-profile-header">${doctorAvatar(d)}<div><p>${esc(d.speciality)}</p><h2>${esc(d.name)}</h2><small>${esc(d.qualification)}</small></div></div><div class="doctor-profile-facts"><div><small>Consultation charge</small><strong>${money(d.fee)}</strong></div><div><small>Experience</small><strong>${d.experience} years</strong></div></div><p class="muted">${esc(d.bio||'Patient-first care with time for your questions. This is a fictional demo profile.')}</p>${d.clinic?`<p class="doctor-contact-line">${icon('location')} ${esc(d.clinic)}${d.city?', '+esc(d.city):''}</p>`:''}<p class="doctor-contact-line">${icon('doctor')} ${esc(d.registration)}</p><p class="doctor-contact-line">${icon('info')} Languages: ${esc(languages)}</p><div class="card section"><h3>Weekly availability</h3><p>${d.days.join(' · ')}</p><p>${d.start} – ${d.end} · ${d.duration}-minute appointments</p><small>Choose your date and an available time in the next step.</small></div><p class="photo-disclaimer section">Fictional demo profile${doctorPhoto(d).startsWith('assets/doctors/')?' · Stock photo portrait':''}</p><div class="section">${btn('Book Appointment '+icon('arrow'),'book','data-id="'+id+'"','doctor-profile-cta')}</div>`);
}
function bookingView(){const d=doctor(booking.doctor);if(booking.step===1){const available=slots(d,booking.date);dialog('Book your appointment',`<div class="eyebrow section">Step 1 of 3 · Visit details</div><p><strong>${esc(d.name)}</strong> · ${esc(d.speciality)}</p><form id="booking-form">${patientSelect('patient',booking.patient)}${field('Appointment date','date',booking.date,'date',`required min="${day()}"`)}<label>Available time<select name="time" required>${available.length?available.map(t=>`<option ${t===booking.time?'selected':''}>${t}</option>`).join(''):'<option value="">No slots on this date — choose another day</option>'}</select></label>${select('Appointment type','type',['Offline','Online'],booking.type)}<small>Online appointments are scheduling only. No audio or video calling is included.</small>${btn('Review appointment →','submit','type="submit" '+(!available.length?'disabled':''))}</form>`);}else if(booking.step===2){dialog('Review your appointment',`<div class="eyebrow section">Step 2 of 3 · Make sure everything looks right</div>${bookingSummary()}<div class="row section">${btn('← Edit details','booking-back','','secondary')}${btn('Continue to payment →','payment')}</div>`);}else{dialog('Secure demo checkout',`<div class="eyebrow section">Step 3 of 3 · Simulated payment</div>${bookingSummary()}<form id="payment-form">${select('Payment method','method',['UPI (demo)','Debit / Credit card (demo)','Net banking (demo)'])}${select('Demo payment result','result',['Successful','Failed'])}<p class="notice section">This is a simulated transaction. No account or card details are collected.</p>${btn('Pay '+money(d.fee)+' →','submit','type="submit"')}</form>`);}}
function bookingSummary(){return `<div class="card section"><h3>${esc(doctor(booking.doctor).name)}</h3><p>${esc(patient(booking.patient).name)}</p><p>${pretty(booking.date)} · ${booking.time} · ${booking.type}</p><div class="row list-item"><span>Consultation fee</span><strong>${money(doctor(booking.doctor).fee)}</strong></div><div class="row"><span>Total</span><strong>${money(doctor(booking.doctor).fee)}</strong></div></div>`;}
function appointmentCard(a){const d=doctor(a.doctor);return `<article class="card appointment-card"><div class="row appointment-status"><span class="badge ${a.status==='Scheduled'?'':'warn'}"><i></i>${a.status==='Scheduled'?'Confirmed':a.status}</span><span class="appointment-token">Token <strong>#${a.token}</strong></span></div><div class="flex appointment-person">${doctorAvatar(d)}<div><h3>${esc(d.name)}</h3><p>${esc(d.speciality)}</p><small>For ${esc(patient(a.patient).name)}</small></div></div><div class="appointment-datetime"><span>${icon('calendar')} ${pretty(a.date)}</span><span>${icon('clock')} ${a.time}</span><span>${a.type==='Offline'?'In clinic':'Online'}</span></div><footer class="row"><span class="payment-label">${icon('check')} ${a.payment} <span>· ${money(a.fee)}</span></span>${btn('View details '+icon('arrow'),role==='doctor'?'consult':'appointment-detail','data-id="'+a.id+'"','secondary')}</footer></article>`;}
function appointments(){const list=state.appointments.filter(a=>appointmentTab==='Completed'?a.status==='Completed':a.status==='Scheduled'&&(appointmentTab==='Today'?a.date===day():a.date>day())).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return `${heading('My appointments','A clear view of your care journey.',btn('Book a visit +','navigate','data-screen="doctors"'))}<div class="chips">${['Today','Upcoming','Completed'].map(t=>`<button class="chip ${appointmentTab===t?'active':''}" data-action="appointment-tab" data-value="${t}">${t}</button>`).join('')}</div><div class="grid two">${list.map(appointmentCard).join('')||empty('No '+appointmentTab.toLowerCase()+' appointments.')}</div>`;}
function detail(id){const a=state.appointments.find(a=>a.id===id);dialog('Appointment details',`<span class="badge section">${a.status}</span><h3 class="section">${esc(doctor(a.doctor).name)}</h3><p>${esc(patient(a.patient).name)} · ${pretty(a.date)} · ${a.time}</p><div class="card"><p>Appointment ID: ${a.id}</p><p>Type: ${a.type}</p><p>Payment: ${a.payment} · ${money(a.fee)}</p><p>Token: #${a.token}</p><p>Queue: ${queueStatus(a).label}</p></div><div class="row section">${btn('View queue','appointment-queue','data-id="'+a.id+'"','secondary')}${btn('Invoice ↓','invoice','data-id="'+a.id+'"','secondary')}</div>`);}
function queueKey(a){return a.doctor+'|'+a.date;}
function queueStatus(a){const current=state.queues[queueKey(a)]??8,ahead=Math.max(0,a.token-current);return {current,ahead,label:a.status==='Completed'||current>a.token?'Completed':current===a.token?'Your Turn':ahead<=2?'Approaching':'Waiting'};}
let queueAppointment='';
function queue(){const list=state.appointments.filter(a=>a.status==='Scheduled'&&(role!=='doctor'||a.doctor===doctorId));const a=list.find(a=>a.id===queueAppointment)||list[0];if(!a)return heading('Token & queue','Your place in line, without the uncertainty.')+empty('No active appointments. Book a visit to get a token.');queueAppointment=a.id;const q=queueStatus(a);return `${heading(role==='doctor'?'Manage your queue':'Your place in line','A little less waiting. A little more peace of mind.')}<div class="narrow" style="max-width:650px"><label>Appointment<select id="queue-select">${list.map(x=>`<option value="${x.id}" ${x.id===a.id?'selected':''}>${esc(patient(x.patient).name)} · ${doctor(x.doctor).name} · ${pretty(x.date)} ${x.time}</option>`).join('')}</select></label><div class="card section" style="text-align:center"><span class="badge">${q.label}</span><h3 class="section">${esc(doctor(a.doctor).name)}</h3><small>${pretty(a.date)} · ${a.time}</small><div class="grid token-grid section"><div><small>Current token</small><div class="token">${String(q.current).padStart(2,'0')}</div></div><div><small>${role==='doctor'?'Patient token':'Your token'}</small><div class="token" style="color:var(--teal)">${a.token}</div></div></div><p>${q.ahead} ${q.ahead===1?'patient':'patients'} ahead</p><p class="muted">${q.label==='Your Turn'?'Please proceed to your consultation.':'Queue updates are simulated for this prototype.'}</p>${btn(role==='doctor'?'Next token →':'Simulate queue →','advance-queue','data-id="'+a.id+'"')}${role==='doctor'?`<div class="section">${btn('Open patient','consult','data-id="'+a.id+'"','secondary')}</div>`:''}</div></div>`;}
function records(){const list=state.records.filter(r=>r.patient===selectedPatient);return `${heading('Medical records','Your health story, always within reach.',btn('Upload record +','upload'))}<div class="toolbar" style="max-width:400px">${patientSelect()}</div><div class="grid two">${list.map(r=>`<article class="card"><span class="icon">${icon('record')}</span><span class="badge">${esc(r.type)}</span><h3 class="section">${esc(r.title)}</h3><p class="muted">${pretty(r.date)} · ${esc(r.source||'Self uploaded')}</p>${btn('Open record →','record','data-id="'+r.id+'"','secondary')}</article>`).join('')||empty('No records for this family member yet. Upload a document to get started.')}</div><div class="section">${btn('View prescriptions →','navigate','data-screen="prescriptions"','secondary')}</div>`;}
function prescriptions(){const list=state.prescriptions.filter(p=>p.patient===selectedPatient);return `${heading('Prescriptions','Clear instructions for the next step in your care.')}<div class="toolbar" style="max-width:400px">${patientSelect()}</div><div class="grid two">${list.map(p=>`<div class="card"><span class="icon">${icon('prescription')}</span><h3>${esc(doctor(p.doctor).name)}</h3><p class="muted">${pretty(p.date)} · ${esc(patient(p.patient).name)}</p><p>${p.medicines.length} prescribed medicine${p.medicines.length>1?'s':''}</p>${btn('View prescription →','rx','data-id="'+p.id+'"','secondary')}</div>`).join('')||empty('No prescriptions for this patient yet.')}</div>`;}
function showRx(id){const p=state.prescriptions.find(r=>r.id===id);dialog('Digital prescription',`<div class="notice section">Fictional demo prescription. Not for medical use.</div><h3 class="section">${esc(doctor(p.doctor).name)}</h3><p>${esc(patient(p.patient).name)} · ${pretty(p.date)}</p>${p.medicines.map(m=>`<div class="medicine"><h3>${esc(m.name)}</h3><p>${esc(m.dosage)} · ${esc(m.frequency)} · ${esc(m.duration)}</p><small>${esc(m.instructions)}</small></div>`).join('')}<p>${esc(p.notes)}</p>${btn('Download prescription ↓','download-rx','data-id="'+p.id+'"','secondary')}`);}
function family(){return `${heading('Your family, cared for','Keep everyone’s health together, with separate records.',btn('Add member +','family-edit'))}<div class="grid section">${state.family.map(p=>`<div class="card"><span class="avatar">${esc(p.name.charAt(0))}</span><h3 class="section">${esc(p.name)}</h3><p class="muted">${p.relationship} · ${p.age} years · ${p.gender}</p><div class="row">${btn('Edit','family-edit','data-id="'+p.id+'"','secondary')}${btn('View health profile →','family-detail','data-id="'+p.id+'"','secondary')}</div></div>`).join('')}</div>`;}
function familyEdit(id){const p=state.family.find(f=>f.id===id)||{};dialog(id?'Edit family member':'Add family member',`<form id="family-form" data-id="${id||''}">${field('Full name','name',p.name,'text','required maxlength="80"')}${field('Age','age',p.age,'number','required min="0" max="120"')}${select('Gender','gender',['Female','Male','Other'],p.gender)}${select('Relationship','relationship',['Mother','Father','Partner','Child','Sibling','Other'],p.relationship)}${btn('Save member','submit','type="submit"')}</form>`);}
function profileForm(setup=false){return `<div class="card narrow"><h2>${setup?'Set up your health profile':'Edit your profile'}</h2><form id="profile-form">${field('Full name','name',setup?'':state.profile.name,'text','required maxlength="80"')}${field('Age','age',setup?'':state.profile.age,'number','required min="1" max="120"')}${select('Gender','gender',['Female','Male','Other'],state.profile.gender)}${field('Mobile number','mobile',setup?authMobile:state.profile.mobile,'tel','required pattern="[6-9][0-9]{9}" maxlength="10"')}${field('Emergency contact','emergency',setup?'':state.profile.emergency,'tel','required pattern="[6-9][0-9]{9}" maxlength="10"')}${btn('Save & continue →','submit','type="submit"')}</form></div>`;}
function profile(){const isDoc=role==='doctor',p=isDoc?doctor(doctorId):state.profile;return `${heading('Your profile','A little about you. A lot of control.')}<div class="grid two section"><div class="card">${isDoc?doctorAvatar(p):`<div class="avatar">${esc(p.name.charAt(0))}</div>`}<h2 class="section">${esc(p.name)}</h2><p class="muted">+91 ${esc(p.mobile)}</p><span class="badge">${isDoc?p.status:'Demo patient account'}</span><div class="section">${btn('Edit profile','edit-profile','','secondary')}</div>${!isDoc?`<p class="section">Emergency contact: ${esc(p.emergency)}</p>${btn('Manage family →','navigate','data-screen="family"','secondary')}`:`<p class="section">${esc(p.qualification)} · ${esc(p.speciality)}</p><p>Registration: ${esc(p.registration)}</p>`}</div><div class="card"><span class="icon">${icon('shield')}</span><h3>Privacy & consent</h3><p class="muted">This local prototype stores fictional data in your browser. It does not provide production authentication or protected medical storage.</p><label><input type="checkbox" id="consent" ${state.profile.consent?'checked':''}> Allow demo doctor access to patient records</label><p class="muted section">You can reset all demo information from the launcher.</p>${btn('Log out','logout','','secondary')}</div></div>`;}
function notifications(){const list=state.notifications.filter(n=>n.audience===role||n.audience==='all');return `${heading('Your updates','The things you need to know, all together.',btn('Mark all read','read-all','','secondary'))}<div class="card section">${list.map(n=>`<div class="list-item row"><div><span class="badge ${n.read?'warn':''}">${n.read?'Read':'New'}</span><h3 style="margin-top:8px">${esc(n.title)}</h3><p class="muted">${esc(n.message)}</p></div>${btn('Open →','notification','data-id="'+n.id+'"','secondary')}</div>`).join('')||'<p>No updates yet.</p>'}</div>`;}
function registration(){return `<div class="card narrow"><div class="eyebrow">Join our care network</div><h2>Doctor registration</h2><p class="muted">Professional details and documents are reviewed by the demo admin.</p><form id="registration-form">${field('Full name','name','','text','required')}${field('Mobile','mobile',authMobile,'tel','required pattern="[6-9][0-9]{9}"')}${field('Qualification','qualification','','text','required')}${field('Experience (years)','experience','','number','required min="0" max="60"')}${field('Medical registration number','registration','','text','required')}${select('Speciality','speciality',[...new Set(state.doctors.map(d=>d.speciality))])}${field('Consultation fee (₹)','fee',500,'number','required min="100" max="10000"')}${field('Qualification document','qualificationDoc','','file','required accept=".pdf,image/*"')}${field('Medical registration document','registrationDoc','','file','required accept=".pdf,image/*"')}${field('KYC document','kycDoc','','file','required accept=".pdf,image/*"')}<small>Use fictional documents only. File names are retained for this local review.</small>${btn('Submit for verification →','submit','type="submit"')}</form></div>`;}
function doctorPanel(){const d=doctor(doctorId);if(d.blocked)return empty('Your demo doctor account is blocked. An admin can unblock it in Doctors.');if(d.status!=='Approved')return `<div class="narrow card"><span class="icon">${icon('clock')}</span><h2>Verification ${d.status.toLowerCase()}</h2><p class="muted">${d.status==='Rejected'?esc(d.rejection||'Please resubmit your application.'):'Your registration has been submitted. Switch to Admin → KYC Verification to review it.'}</p>${btn('Refresh verification status','refresh','','secondary')}${d.status==='Rejected'?btn('Resubmit application','resubmit','','secondary'):''}</div>`;if(screen==='schedule')return schedule();const list=state.appointments.filter(a=>a.doctor===doctorId&&a.date===doctorDay).sort((a,b)=>a.time.localeCompare(b.time));return `${heading('Welcome back, '+esc(d.name.split(' ').slice(0,2).join(' ')),'A good day to make someone feel better.')}<div class="grid section">${[['Today’s appointments',day()],['Tomorrow’s appointments',day(1)],['Total scheduled',null]].map(([l,date])=>`<div class="card"><small>${l}</small><div class="stat">${state.appointments.filter(a=>a.doctor===doctorId&&a.status==='Scheduled'&&(!date||a.date===date)).length}</div><span class="badge">Your practice, at a glance</span></div>`).join('')}</div><div class="toolbar">${btn('Today','doctor-day','data-value="'+day()+'"',doctorDay===day()?'':'secondary')}${btn('Tomorrow','doctor-day','data-value="'+day(1)+'"',doctorDay===day(1)?'':'secondary')}<input type="date" id="doctor-calendar" aria-label="Appointment calendar" value="${doctorDay}"></div><h2>Appointments · ${pretty(doctorDay)}</h2><div class="grid two">${list.map(appointmentCard).join('')||empty('No appointments on this date.')}</div>`;}
function schedule(){const d=doctor(doctorId);return `${heading('Your schedule','Make time for the care you give.')}<form id="schedule-form" class="card narrow"><h3>Working days</h3><div class="chips">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(w=>`<label class="chip"><input type="checkbox" name="days" value="${w}" ${d.days.includes(w)?'checked':''}> ${w}</label>`).join('')}</div><div class="grid two">${field('Start time','start',d.start,'time','required')}${field('End time','end',d.end,'time','required')}</div>${select('Slot duration (minutes)','duration',['15','20','30','45','60'],String(d.duration))}<p class="notice section">Saved availability updates this doctor’s patient booking slots.</p>${btn('Save schedule','submit','type="submit"')}</form>`;}
function consult(id){const a=state.appointments.find(a=>a.id===id),p=patient(a.patient);dialog('Patient consultation',`<span class="badge section">Token #${a.token} · ${a.status}</span><h2 class="section">${esc(p.name)}</h2><p>${p.age} years · ${p.gender} · ${pretty(a.date)} · ${a.time}</p><div class="chips">${btn('Medical history','history','data-patient="'+a.patient+'"','secondary')}${btn('New prescription','prescribe','data-id="'+id+'"','secondary')}</div><form id="consult-form" data-id="${id}"><label>Consultation notes<textarea name="notes" required>${esc(a.notes||'')}</textarea></label>${select('Appointment status','status',['Scheduled','In consultation','Completed'],a.status)}${btn('Save consultation','submit','type="submit"')}</form><div class="section">${btn('Complete appointment ✓','complete','data-id="'+id+'"','teal')}</div>`);}
function history(patientId){if(!state.profile.consent){dialog('Medical history','<p class="notice section">Patient consent is disabled. Enable it in the patient privacy settings to view demo records.</p>');return;}const records=state.records.filter(r=>r.patient===patientId),rx=state.prescriptions.filter(r=>r.patient===patientId);dialog('Patient health history',`<h3 class="section">${esc(patient(patientId).name)}</h3><h3>Records & reports</h3>${records.map(r=>`<div class="list-item">${esc(r.title)} · ${pretty(r.date)} ${btn('Open','record','data-id="'+r.id+'"','secondary')}</div>`).join('')||'<p class="muted">No previous records.</p>'}<h3 class="section">Previous prescriptions</h3>${rx.map(r=>`<div class="list-item">${pretty(r.date)} · ${doctor(r.doctor).name} ${btn('View','rx','data-id="'+r.id+'"','secondary')}</div>`).join('')||'<p class="muted">No previous prescriptions.</p>'}`);}
function medicineRow(){return `<div class="medicine"><div class="row"><strong>Medicine details</strong><button type="button" class="plain" data-action="remove-medicine">Remove ✕</button></div>${field('Medicine name','medicine','','text','required') }<div class="grid two">${field('Dosage','dosage','','text','required placeholder="e.g. 1 tablet"')}${field('Frequency','frequency','','text','required placeholder="e.g. Twice daily"')}${field('Duration','duration','','text','required placeholder="e.g. 3 days"')}${field('Instructions','instructions','','text','required')}</div></div>`;}
function prescribe(id){dialog('Create digital prescription',`<p class="notice section">Use fictional medicines only. This is a prototype, not a clinical tool.</p><form id="prescription-form" data-id="${id}"><div id="medicine-rows">${medicineRow()}</div>${btn('Add another medicine +','add-medicine','type="button"','secondary')}<label>Doctor notes<textarea name="notes"></textarea></label>${btn('Save prescription →','submit','type="submit"')}</form>`);}
const adminTabs=['Dashboard','Patients','Doctors','KYC Verification','Appointments','Payments','Commission','Complaints / Support','Notifications','Reports & Analytics','Roles & Access','Audit Logs'];
let adminSearch='',adminDate='',adminStatus='',adminDoctor='';
function admin(){return `<div class="row" style="margin-bottom:20px"><span class="eyebrow">Administration / ${adminTab}</span><button class="btn secondary mobile-menu" data-action="admin-menu">${icon('menu')} Menu</button></div><div class="admin-shell"><aside class="sidebar" id="sidebar">${adminTabs.map(t=>`<button class="${adminTab===t?'active':''}" data-action="admin-tab" data-value="${t}">${t}</button>`).join('')}</aside><section class="admin-content">${adminContent()}</section></div>`;}
function adminToolbar(extra=''){return `<div class="toolbar"><input id="admin-search" placeholder="Search ${adminTab.toLowerCase()}…" aria-label="Search" value="${esc(adminSearch)}">${extra}</div>`;}
function table(headers,rows){return `<div class="card table-wrap"><table><thead><tr>${headers.map(h=>'<th>'+h+'</th>').join('')}</tr></thead><tbody>${rows.length?rows.map(r=>'<tr>'+r.map(v=>'<td>'+v+'</td>').join('')+'</tr>').join(''):`<tr><td colspan="${headers.length}">No matching data.</td></tr>`}</tbody></table></div>`;}
function match(v){return JSON.stringify(v).toLowerCase().includes(adminSearch.toLowerCase());}
function adminContent(){let title=heading(adminTab,adminTab==='Dashboard'?'A healthier network starts with a clearer picture.':'Manage your connected demo healthcare platform.');let content='';
if(adminTab==='Dashboard'){const paid=state.appointments.filter(a=>a.payment==='Successful').reduce((n,a)=>n+a.fee,0);content=`<div class="grid section">${[['Total patients',state.family.length+1],['Total doctors',state.doctors.length],['Appointments',state.appointments.length],['Pending KYC',state.doctors.filter(d=>d.status==='Pending').length],['Payments',money(paid)],['Open complaints',state.complaints.filter(c=>c.status==='Open').length]].map(([l,n])=>`<div class="card"><small>${l}</small><div class="stat">${n}</div><span class="badge">Live demo data</span></div>`).join('')}</div><div class="grid two section"><div class="card"><h3>Appointment trends</h3>${chart()}</div><div class="card"><h3>Payment summary</h3><div class="stat">${money(paid)}</div><p class="muted">Successful consultation payments</p><div class="list-item row"><span>Platform commission</span><strong>${money(paid*state.commission/100)}</strong></div><div class="row"><span>Registered profiles</span><strong>${state.doctors.length+state.family.length+1}</strong></div></div></div>`;}
else if(adminTab==='Doctors'){content=adminDoctorsView();}
else if(adminTab==='Patients'){content=adminToolbar()+table(['Name','Details','Status','Actions'],[state.profile,...state.family].filter(match).map(p=>[esc(p.name),`${p.age} years · ${p.gender}`,`<span class="badge ${p.blocked?'warn':''}">${p.blocked?'Blocked':'Active'}</span>`,btn('View','admin-person','data-id="'+p.id+'" data-kind="patient"','secondary')+' '+btn(p.blocked?'Unblock':'Block','block','data-id="'+p.id+'" data-kind="patient"',p.blocked?'secondary':'danger')]));}
else if(adminTab==='KYC Verification'){content=adminToolbar()+table(['Doctor','Registration','Status','Review'],state.doctors.filter(match).map(d=>[esc(d.name),esc(d.registration),`<span class="badge ${d.status==='Pending'?'warn':''}">${d.status}</span>`,btn('Review documents','kyc','data-id="'+d.id+'"','secondary')]));}
else if(adminTab==='Appointments'){content=adminToolbar(`<input type="date" id="admin-date" aria-label="Filter date" value="${adminDate}"><select id="admin-doctor" aria-label="Filter doctor"><option value="">All doctors</option>${state.doctors.map(d=>`<option value="${d.id}" ${adminDoctor===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><select id="admin-status" aria-label="Filter status">${['','Scheduled','In consultation','Completed','Cancelled'].map(s=>`<option ${adminStatus===s?'selected':''} value="${s}">${s||'All statuses'}</option>`).join('')}</select>${btn('Clear filters','clear-filters','','secondary')}`)+table(['Appointment','Patient / Doctor','Date & time','Type / token','Status','Details'],state.appointments.filter(a=>match({...a,name:patient(a.patient).name,doctorName:doctor(a.doctor).name})&&(!adminDate||a.date===adminDate)&&(!adminStatus||a.status===adminStatus)&&(!adminDoctor||a.doctor===adminDoctor)).map(a=>[a.id,esc(patient(a.patient).name)+'<br>'+esc(doctor(a.doctor).name),pretty(a.date)+'<br>'+a.time,a.type+' / #'+a.token,a.status+'<br>'+a.payment,btn('View','appointment-detail','data-id="'+a.id+'"','secondary')]));}
else if(adminTab==='Payments'){content=adminToolbar()+table(['Transaction / appointment','Patient / doctor','Amount','Date','Payment','Actions'],state.appointments.filter(a=>match({...a,patientName:patient(a.patient).name,doctorName:doctor(a.doctor).name})).map(a=>['PAY-'+a.id+'<br>'+a.id,esc(patient(a.patient).name)+'<br>'+esc(doctor(a.doctor).name),money(a.fee),pretty(a.date),a.payment,btn('Invoice','invoice','data-id="'+a.id+'"','secondary')+(a.payment==='Successful'?btn('Refund','refund','data-id="'+a.id+'"','danger'):a.payment==='Refund Pending'?btn('Process refund','process-refund','data-id="'+a.id+'"','secondary'):'')]));}
else if(adminTab==='Commission'){content=`<form id="commission-form" class="card section"><h3>Platform commission</h3>${field('Commission percentage','percent',state.commission,'number','required min="0" max="100" step="0.1"')}${btn('Save configuration','submit','type="submit"')}</form><div class="section">${table(['Appointment','Gross payment','Commission ('+state.commission+'%)','Doctor receives'],state.appointments.filter(a=>a.payment==='Successful').map(a=>[a.id,money(a.fee),money(a.fee*state.commission/100),money(a.fee*(1-state.commission/100))]))}</div>`;}
else if(adminTab==='Complaints / Support'){content=adminToolbar()+table(['Reference','User','Subject','Date','Status','Action'],state.complaints.filter(match).map(c=>[c.id,esc(c.user),esc(c.subject),pretty(c.date),c.status,btn('View / update','complaint','data-id="'+c.id+'"','secondary')]));}
else if(adminTab==='Notifications'){content=`<form id="notification-form" class="card section">${field('Notification title','title','','text','required maxlength="100"')}<label>Message<textarea name="message" required></textarea></label>${select('Audience','audience',[['all','Everyone'],['patient','Patients'],['doctor','Doctors']])}${btn('Send notification →','submit','type="submit"')}</form><div class="card section"><h3>Sent updates</h3>${state.notifications.map(n=>`<div class="list-item"><strong>${esc(n.title)}</strong><p class="muted">${esc(n.message)}</p><small>Audience: ${n.audience}</small></div>`).join('')}</div>`;}
else if(adminTab==='Reports & Analytics'){const list=state.appointments.filter(a=>(!adminDate||a.date===adminDate)&&(!adminStatus||a.status===adminStatus)),total=list.filter(a=>a.payment==='Successful').reduce((s,a)=>s+a.fee,0);content=`<div class="toolbar"><input type="date" id="admin-date" value="${adminDate}" aria-label="Report date"><select id="admin-status" aria-label="Report status">${['','Scheduled','Completed'].map(s=>`<option value="${s}" ${adminStatus===s?'selected':''}>${s||'All statuses'}</option>`).join('')}</select>${btn('Clear','clear-filters','','secondary')}${btn('Export CSV ↓','export','','secondary')}</div><div class="grid">${[['Appointments',list.length],['Payments',money(total)],['Commission',money(total*state.commission/100)],['Patients',state.family.length+1],['Doctors',state.doctors.length],['Platform activity',state.logs.length]].map(([l,v])=>`<div class="card"><small>${l}</small><div class="stat">${v}</div></div>`).join('')}</div><div class="card section"><h3>Appointments · last 7 days</h3>${chart(list)}</div><div class="section">${table(['Appointment','Date','Status','Payment'],list.map(a=>[a.id,pretty(a.date),a.status,money(a.fee)+' · '+a.payment]))}</div>`;}
else if(adminTab==='Roles & Access'){content=`<div class="notice section">Permissions are persisted demo configuration. This browser-only prototype does not enforce production access control.</div><form id="roles-form"><div class="grid section">${Object.entries(state.roles).map(([r,permissions])=>`<div class="card"><h3>${r}</h3><p class="muted">Platform module permissions</p>${['View','Add','Edit'].map(p=>`<label><input type="checkbox" name="${r}" value="${p}" ${permissions.includes(p)?'checked':''}> ${p}</label>`).join('')}<p class="muted section">${r==='Support'?'Complaints, notifications':r==='Operations'?'Patients, doctors, appointments':'All platform modules'}</p></div>`).join('')}</div>${btn('Save permissions','submit','type="submit"')}</form>`;}
else if(adminTab==='Audit Logs'){content=adminToolbar()+table(['Time','Actor','Action','Module','Reference','Status'],state.logs.filter(match).map(l=>[new Date(l.date).toLocaleString('en-IN'),esc(l.actor),esc(l.action),esc(l.module),esc(l.reference),l.status]));}
else{content=empty('Choose a section from the admin navigation.');}
return title+content;}
function chart(list=state.appointments){let counts=Array.from({length:7},(_,i)=>({date:day(i-6),count:list.filter(a=>a.date===day(i-6)).length})),max=Math.max(1,...counts.map(c=>c.count));return `<div class="bar-chart">${counts.map(c=>`<div title="${pretty(c.date)}: ${c.count} appointments" style="height:${Math.max(4,c.count/max*100)}%"><small>${new Date(c.date+'T12:00:00').toLocaleDateString('en-IN',{weekday:'short'})}<br>${c.count}</small></div>`).join('')}</div><div style="height:28px"></div>`;}
function download(filename,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function invoice(id){const a=state.appointments.find(a=>a.id===id);download('Invoice-'+id+'.txt',`MY DOCTOR — DEMO INVOICE\nNot a tax invoice. No real payment collected.\n\nReference: ${a.id}\nPatient: ${patient(a.patient).name}\nDoctor: ${doctor(a.doctor).name}\nDate: ${a.date} ${a.time}\nConsultation: ${money(a.fee)}\nPayment: ${a.payment}`);toast('Demo invoice downloaded');}
function showRecord(id){const r=state.records.find(r=>r.id===id);dialog('Medical document',`<span class="badge section">${esc(r.type)}</span><h2 class="section">${esc(r.title)}</h2><p>${esc(patient(r.patient).name)} · ${pretty(r.date)}</p><p>Source: ${esc(r.source||'Self uploaded')}</p><p>File: ${esc(r.filename||'Digital prescription')}</p><p>${esc(r.notes||'No additional notes.')}</p>${r.data?btn('Download document ↓','download-record','data-id="'+id+'"','secondary'):r.rx?btn('View prescription','rx','data-id="'+r.rx+'"','secondary'):'<p class="notice">Seeded demo record: metadata preview only.</p>'}`);}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id,value=el.dataset.value;
switch(action){case 'submit':return;case 'close':modal.close();break;case 'home':go(role?'home':'launcher');break;case 'launcher':role='';go('launcher');break;case 'role':role=el.dataset.role;if(role==='admin'){adminTab='Dashboard';go('home');}else{authRole=role;go('auth');}break;case 'navigate':go(el.dataset.screen);break;case 'notifications':if(role==='admin'){adminTab='Notifications';render();}else go('notifications');break;case 'profile':if(role==='admin'){toast('Demo session: Super Admin. Use Roles & Access to configure permissions.');}else go('profile');break;case 'resend':toast('Demo OTP resent: 1234');break;case 'speciality':filter=value;document.querySelectorAll('.speciality-rail .chip').forEach(chip=>{const active=chip.dataset.value===value;chip.classList.toggle('active',active);chip.setAttribute('aria-pressed',String(active));});$('#doctor-list').innerHTML=doctorList();break;case 'doctor-profile':showDoctor(id);break;case 'book':if(state.profile.blocked){toast('This patient account is blocked. Contact the demo admin.');break;}booking={doctor:id,patient:'self',date:day(),time:'',type:'Offline',step:1};bookingView();break;case 'booking-back':booking.step=1;bookingView();break;case 'payment':booking.step=3;bookingView();break;case 'appointment-tab':appointmentTab=value;render();break;case 'appointment-detail':detail(id);break;case 'appointment-queue':queueAppointment=id;modal.close();go('queue');break;case 'advance-queue':{let a=state.appointments.find(a=>a.id===id);state.queues[queueKey(a)]=(state.queues[queueKey(a)]??8)+1;notify('Queue update','Current token: '+state.queues[queueKey(a)]+'. Your token: '+a.token,'patient','queue');audit('Queue advanced','Queue',a.id);render();break;}case 'upload':dialog('Upload a medical record',`<form id="upload-form">${field('Record title','title','','text','required')}${select('Record type','type',['Medical Record','Lab Report','Other Medical Document','Prescription'])}${patientSelect()}${field('Record date','date',day(),'date','required')}${field('Doctor / source','source')}${field('Document (up to 2 MB)','file','','file','required accept=".pdf,.png,.jpg,.jpeg,.txt"')}<label>Notes<textarea name="notes"></textarea></label>${btn('Upload record →','submit','type="submit"')}</form>`);break;case 'record':showRecord(id);break;case 'download-record':{const r=state.records.find(r=>r.id===id),a=document.createElement('a');a.href=r.data;a.download=r.filename;a.click();break;}case 'rx':showRx(id);break;case 'download-rx':{const p=state.prescriptions.find(p=>p.id===id);download('Prescription-'+id+'.txt','FICTIONAL DEMO — NOT FOR MEDICAL USE\n'+doctor(p.doctor).name+'\n'+patient(p.patient).name+' · '+p.date+'\n\n'+p.medicines.map(m=>Object.values(m).join(' · ')).join('\n')+'\n'+p.notes);break;}case 'family-edit':familyEdit(id);break;case 'family-detail':selectedPatient=id;go('records');break;case 'edit-profile':if(role==='patient')dialog('Patient profile',profileForm());else{const d=doctor(doctorId);dialog('Edit doctor profile',`<form id="doctor-profile-form">${field('Name','name',d.name,'text','required')}${field('Mobile','mobile',d.mobile,'tel','required pattern="[6-9][0-9]{9}"')}<p class="notice section">Consultation charge: ${money(d.fee)}. Set by your platform admin.</p>${btn('Save profile','submit','type="submit"')}</form>`);}break;case 'logout':role='';go('launcher');toast('Demo session ended');break;case 'read-all':state.notifications.filter(n=>n.audience===role||n.audience==='all').forEach(n=>n.read=true);save();render();break;case 'notification':{const n=state.notifications.find(n=>n.id===id);n.read=true;save();go(role==='doctor'?'home':n.link||'home');break;}case 'refresh':render();toast('Verification status refreshed');break;case 'resubmit':doctor(doctorId).status='Pending';audit('KYC resubmitted','KYC',doctorId);render();break;case 'doctor-day':doctorDay=value;render();break;case 'consult':consult(id);break;case 'history':history(el.dataset.patient);break;case 'prescribe':prescribe(id);break;case 'add-medicine':$('#medicine-rows').insertAdjacentHTML('beforeend',medicineRow());break;case 'remove-medicine':if($('#medicine-rows').children.length>1)el.closest('.medicine').remove();else toast('Keep at least one medicine row.');break;case 'complete':{const a=state.appointments.find(a=>a.id===id);a.status='Completed';save();modal.close();render();notify('Consultation completed','Your consultation with '+doctor(a.doctor).name+' is complete.','patient','appointments');toast('Appointment completed');break;}case 'admin-menu':$('#sidebar').classList.toggle('open');break;case 'admin-tab':adminTab=value;adminSearch='';adminDate='';adminStatus='';adminDoctor='';render();break;case 'clear-filters':adminDate='';adminStatus='';adminDoctor='';adminSearch='';render();break;case 'admin-person':{const p=el.dataset.kind==='doctor'?doctor(id):patient(id);dialog('Account details',`<h2 class="section">${esc(p.name)}</h2>${Object.entries(p).filter(([k])=>!['avatar','documents'].includes(k)).map(([k,v])=>`<p><strong>${esc(k)}:</strong> ${esc(Array.isArray(v)?v.join(', '):v)}</p>`).join('')}`);break;}case 'block':{const p=el.dataset.kind==='doctor'?doctor(id):patient(id);if(!confirm((p.blocked?'Unblock ':'Block ')+p.name+' in this prototype?'))break;p.blocked=!p.blocked;audit(p.blocked?'Account blocked':'Account unblocked',el.dataset.kind,id);render();toast('Account status updated');break;}case 'kyc':{const d=doctor(id);dialog('KYC review',`<h3 class="section">${esc(d.name)}</h3><p>${esc(d.qualification)} · ${d.experience} years</p><p>${esc(d.registration)}</p><span class="badge">${d.status}</span><h3 class="section">Documents</h3>${(d.documents||['Demo qualification document','Demo medical registration','Demo KYC document']).map(f=>`<p class="notice">▤ ${esc(f)} · metadata preview</p>`).join('')}<div class="row section">${btn('Approve doctor','kyc-approve','data-id="'+id+'"','teal')}${btn('Reject','kyc-reject','data-id="'+id+'"','danger')}</div>`);break;}case 'kyc-approve':doctor(id).status='Approved';audit('Doctor KYC approved','KYC',id);notify('Verification approved','Your doctor account is approved.','doctor','home');modal.close();render();toast('Doctor approved');break;case 'kyc-reject':{const reason=prompt('Reason for rejection:');if(!reason?.trim())break;doctor(id).status='Rejected';doctor(id).rejection=reason;audit('Doctor KYC rejected','KYC',id);notify('Verification update',reason,'doctor','home');modal.close();render();break;}case 'refund':if(confirm('Request a simulated full refund for '+id+'?')){state.appointments.find(a=>a.id===id).payment='Refund Pending';audit('Refund requested','Payments',id);render();toast('Refund pending. Process it to complete the simulation.');}break;case 'process-refund':{const a=state.appointments.find(a=>a.id===id);a.payment='Refunded';a.status='Cancelled';audit('Refund processed','Payments',id);notify('Refund completed','Demo refund of '+money(a.fee)+' processed for '+id);render();break;}case 'invoice':invoice(id);break;case 'complaint':{const c=state.complaints.find(c=>c.id===id);dialog('Support request',`<h3 class="section">${esc(c.subject)}</h3><p>${esc(c.user)} · ${pretty(c.date)}</p><p>${esc(c.message)}</p><form id="complaint-form" data-id="${id}">${select('Status','status',['Open','In Progress','Resolved','Closed'],c.status)}${btn('Update request','submit','type="submit"')}</form>`);break;}case 'export':{const rows=state.appointments.filter(a=>(!adminDate||a.date===adminDate)&&(!adminStatus||a.status===adminStatus));download('My-Doctor-report.csv','Appointment,Date,Status,Amount,Payment\n'+rows.map(a=>[a.id,a.date,a.status,a.fee,a.payment].join(',')).join('\n'),'text/csv');break;}case 'reset':if(confirm('Reset all demo data? This removes locally saved changes and uploaded demo files.')){state=seed();save();role='';go('launcher');toast('Demo data reset');}break;
}});
document.addEventListener('input',e=>{if(e.target.id==='doctor-search'){search=e.target.value;$('#doctor-list').innerHTML=doctorList();}if(e.target.id==='admin-search'){adminSearch=e.target.value;const pos=e.target.selectionStart;render();$('#admin-search').focus();$('#admin-search').setSelectionRange(pos,pos);}});
document.addEventListener('change',e=>{if(e.target.name==='patient'&&!e.target.closest('dialog')){selectedPatient=e.target.value;render();}if(e.target.id==='queue-select'){queueAppointment=e.target.value;render();}if(e.target.closest('#booking-form')&&e.target.name==='date'){const form=e.target.form;booking.patient=form.patient.value;booking.date=e.target.value;booking.type=form.type.value;bookingView();}if(e.target.id==='consent'){state.profile.consent=e.target.checked;save();toast('Consent preference saved');}if(e.target.id==='doctor-calendar'){doctorDay=e.target.value;render();}if(e.target.id==='admin-date'){adminDate=e.target.value;render();}if(e.target.id==='admin-status'){adminStatus=e.target.value;render();}if(e.target.id==='admin-doctor'){adminDoctor=e.target.value;render();}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,fd=new FormData(f),data=Object.fromEntries(fd);if(!f.checkValidity()){f.reportValidity();return;}
switch(f.id){case 'auth-form':if(screen==='auth'){authMobile=data.mobile;newDoctor=!!data.newDoctor;window.demoNewPatient=!!data.newPatient;screen='otp';render();toast('Demo OTP ready: 1234');}else if(data.otp==='1234'){if(authRole==='patient'){if(state.profile.blocked&&!window.demoNewPatient){toast('This demo account is blocked. Ask the demo admin to unblock it.');return;}go(window.demoNewPatient?'setup':'home');}else if(newDoctor)go('registration');else{doctorId=state.doctors.find(d=>d.mobile===authMobile)?.id||'d0';go('home');}}break;
case 'profile-form':Object.assign(state.profile,data,{age:Number(data.age)});save();if(modal.open)modal.close();go('home');toast('Profile saved');break;
case 'family-form':{const id=f.dataset.id,p={...data,age:Number(data.age)};if(id)Object.assign(state.family.find(p=>p.id===id),p);else state.family.push({id:uid('F'),...p});save();modal.close();render();toast('Family member saved');break;}
case 'booking-form':Object.assign(booking,data,{step:2});bookingView();break;
case 'payment-form':{const submit=f.querySelector('button[type=submit]');submit.disabled=true;submit.textContent='Processing demo payment…';await new Promise(r=>setTimeout(r,1000));if(data.result==='Failed'){toast('Demo payment failed. Try again or select Successful.');submit.disabled=false;submit.textContent='Retry payment';return;}const d=doctor(booking.doctor);if(d.blocked||d.status!=='Approved'||state.profile.blocked){toast('This account is unavailable. Please contact the demo admin.');return;}if(!slots(d,booking.date).includes(booking.time)){toast('This slot is no longer available. Please choose another.');booking.step=1;bookingView();return;}const token=Math.max(8,...state.appointments.filter(a=>a.doctor===d.id&&a.date===booking.date).map(a=>a.token))+1;const a={...booking,id:uid('APT'),fee:d.fee,token,status:'Scheduled',payment:'Successful',method:data.method};delete a.step;state.appointments.push(a);audit('Appointment booked','Appointments',a.id);notify('Appointment confirmed',d.name+' · '+pretty(a.date)+' · Token #'+a.token);notify('New appointment',patient(a.patient).name+' booked '+pretty(a.date)+' at '+a.time,'doctor','home');dialog('Your appointment is confirmed',`<div class="empty" style="padding:20px"><span class="icon" style="margin:auto;background:#e2f7ed;color:var(--teal)">✓</span><h2 class="section">A little closer to better.</h2><p>Demo payment successful · ${money(a.fee)}</p><h3>${esc(d.name)}</h3><p>${pretty(a.date)} · ${a.time}</p><div class="token">#${token}</div><small>Your token · ${a.id}</small><div class="section">${btn('View appointment →','appointment-detail','data-id="'+a.id+'"')}</div></div>`);render();break;}
case 'upload-form':{const file=fd.get('file');if(file.size>2*1024*1024){toast('Please choose a file smaller than 2 MB.');return;}const reader=new FileReader();reader.onload=()=>{state.records.unshift({id:uid('REC'),title:data.title,type:data.type,patient:data.patient,date:data.date,source:data.source,notes:data.notes,filename:file.name,data:reader.result});save();selectedPatient=data.patient;modal.close();render();toast('Record uploaded');};reader.onerror=()=>toast('Unable to read this file. Please try another.');reader.readAsDataURL(file);break;}
case 'registration-form':{const id=uid('DOC');const p={id,name:data.name.startsWith('Dr.')?data.name:'Dr. '+data.name,mobile:data.mobile,qualification:data.qualification,experience:Number(data.experience),registration:data.registration,speciality:data.speciality,fee:Number(data.fee),avatar:'👩🏻‍⚕️',status:'Pending',blocked:false,days:['Mon','Tue','Wed','Thu','Fri','Sat'],start:'09:00',end:'17:00',duration:30,documents:['qualificationDoc','registrationDoc','kycDoc'].map(k=>fd.get(k).name)};state.doctors.push(p);doctorId=id;audit('Doctor registration submitted','KYC',id);go('home');toast('Registration submitted for admin approval');break;}
case 'schedule-form':{if(data.end<=data.start||!fd.getAll('days').length){toast('Choose at least one working day and an end time after the start.');return;}Object.assign(doctor(doctorId),{start:data.start,end:data.end,duration:Number(data.duration),days:fd.getAll('days')});audit('Schedule updated','Doctors',doctorId);toast('Schedule saved. Patient booking slots updated.');break;}
case 'doctor-profile-form':Object.assign(doctor(doctorId),{name:data.name,mobile:data.mobile});save();modal.close();render();toast('Doctor profile saved');break;
case 'consult-form':{const a=state.appointments.find(a=>a.id===f.dataset.id);a.notes=data.notes;a.status=data.status;save();modal.close();render();toast('Consultation saved');break;}
case 'prescription-form':{const a=state.appointments.find(a=>a.id===f.dataset.id),rx={id:uid('RX'),doctor:a.doctor,patient:a.patient,date:day(),notes:data.notes,medicines:fd.getAll('medicine').map((name,i)=>({name,dosage:fd.getAll('dosage')[i],frequency:fd.getAll('frequency')[i],duration:fd.getAll('duration')[i],instructions:fd.getAll('instructions')[i]}))};state.prescriptions.push(rx);state.records.unshift({id:uid('REC'),title:'Prescription · '+doctor(a.doctor).name,type:'Prescription',patient:a.patient,date:rx.date,source:doctor(a.doctor).name,rx:rx.id,notes:rx.notes});notify('New prescription','Your digital prescription from '+doctor(a.doctor).name+' is ready.','patient','prescriptions');audit('Prescription created','Prescriptions',rx.id);modal.close();render();toast('Prescription saved to patient records');break;}
case 'commission-form':state.commission=Number(data.percent);audit('Commission changed to '+data.percent+'%','Commission');render();toast('Commission calculation updated');break;
case 'notification-form':notify(data.title,data.message,data.audience,'notifications');audit('Notification sent','Notifications',data.audience);render();toast('Notification sent to demo audience');break;
case 'complaint-form':state.complaints.find(c=>c.id===f.dataset.id).status=data.status;audit('Support status updated','Support',f.dataset.id);modal.close();render();toast('Support request updated');break;
case 'roles-form':Object.keys(state.roles).forEach(r=>state.roles[r]=fd.getAll(r));audit('Role permissions updated','Roles');render();toast('Permissions saved');break;
}});
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){state=JSON.parse(e.newValue);render();}});
save();render();
